(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*12 + Math.cos(y*0.013-t*0.18)*8;
  const w2 = Math.cos(x*0.009+y*0.007+t*0.15)*20;
  const w3 = Math.sin((x+y)*0.012-t*0.22)*10;
  const sx = x + w1 + w2, sy = y + w1*0.7 + w3;
  const src = [
    [120+Math.sin(t*0.5)*110, 60+Math.cos(t*0.35)*45, 0.075, 2.1, 1.0],
    [360+Math.cos(t*0.45)*90, 100+Math.sin(t*0.6)*55, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.3+2)*150, 140+Math.cos(t*0.5+1)*80, 0.055, 2.5, 1.2],
    [80+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.55+3)*50, 0.11, 1.6, 0.9],
    [400+Math.sin(t*0.38+4)*80, 180+Math.cos(t*0.85+2)*60, 0.065, 2.8, 1.1],
    [200+Math.cos(t*0.32+5)*100, 40+Math.sin(t*0.48)*70, 0.085, 2.0, 0.85],
    [320+Math.sin(t*0.42+3)*60, 210+Math.cos(t*0.28+4)*40, 0.1, 1.9, 0.95],
    [160+Math.cos(t*0.55+2)*90, 130+Math.sin(t*0.4+5)*60, 0.07, 2.3, 1.05]
  ];
  let aS = 0, iS = 0, cS = 0, totW = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const att = w / (1 + d*0.003);
    aS += Math.sin(d*f - t*sp) * att;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.2) * att;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.8) * att * 0.5;
    totW += att;
  }
  aS /= totW; iS /= totW; cS /= totW;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.7) + Math.sin(sx*0.025-sy*0.035+t*0.95))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.15 + Math.sin((sx-sy)*0.08-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.3) + Math.sin(dist*0.035+ang*5-t*1.05))*0.35;
  const radial = Math.sin(dist*0.08 - t*1.5)*0.2*Math.cos(ang*2+t*0.3);
  const cross = Math.tanh(aS*iS*2.5)*0.3;
  const reaction = Math.tanh((aS - iS*0.65 + cS*0.4 + bg*0.25 + spiral + radial + cross)*2.0);
  const vx = Math.sin(sx*0.12)*Math.sin(sy*0.12+t*0.3);
  const vy = Math.sin(sx*0.1-t*0.2)*Math.sin(sy*0.13);
  const cell = Math.tanh((vx+vy+Math.sin((sx-sy)*0.08+t*0.5)*0.4)*1.8)*0.25;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.65 + cell*0.25 + micro;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [
    [6,12,52],[12,42,88],[18,78,112],[25,128,128],[55,165,118],
    [140,190,85],[210,195,60],[235,165,55],[230,120,65],[200,75,72],
    [155,48,82],[95,25,65],[50,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.75 ? 1.12 : (Math.abs(reaction)>0.5 ? 1.05 : 1.0);
  const glow = Math.max(0, reaction-0.5)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge + glow*15)|0)
  ];
}
